class App:
    def __init__(self):
        self.routes = {}
    def route(self, path):
        def register(func):
            self.routes[path] = func
            return func
        return register

app = App()

@app.route('/')
def home():
    return 'Welcome'

@app.route('/about')
def about():
    return 'About us'

print(sorted(app.routes), app.routes['/about']())

