solution.code:
def dispatch(routes, path):
    view = routes.get(path)
    if view is None:
        return '404 Not Found'
    return view()

def dispatch_many(routes, paths):
    result = []
    for path in paths:
        view = routes.get(path)
        result.append('404 Not Found' if view is None else view())
    return result

def render(template, context):
    for key, value in context.items():
        template = template.replace('{{' + key + '}}', value)
    return template

def render_ul(items):
    inner = ''.join(f'<li>{i}</li>' for i in items)
    return f'<ul>{inner}</ul>'

def render_nav(links):
    inner = ''.join(f'<li><a href="{href}">{label}</a></li>' for label, href in links.items())
    return f'<ul>{inner}</ul>'

