def post_view(method, form):
    if method == 'GET':
        return {'status': 200, 'page': 'form'}
    if method == 'POST':
        text = form['content']
        return {'status': 200, 'words': len(text.split()), 'chars': len(text)}
    return {'status': 405}

def contact_view(method, form):
    if method == 'GET':
        return {'status': 200, 'page': 'contact'}
    if method == 'POST':
        return {'status': 200, 'message': f"Thanks, {form['name']}!"}
    return {'status': 405}

