solution.code:
def parse_procfile(text):
    result = {}
    for line in text.split('\n'):
        if line.strip():
            process, command = line.split(': ', 1)
            result[process] = command
    return result

def run_command(text, process):
    commands = {}
    for line in text.split('\n'):
        if line.strip():
            name, command = line.split(': ', 1)
            commands[name] = command
    return commands.get(process)
